const itemsEntrada = $input.all();

if (itemsEntrada.length !== 1) {
  throw new Error('DISPONIBILIDAD_REQUIERE_UNA_SOLICITUD');
}

const raiz = itemsEntrada[0].json;
const capas = [];
const erroresTransporte = [];

function presente(v) {
  return (
    v !== null &&
    v !== undefined &&
    !(
      typeof v === 'string' &&
      /^(?:\s*|null|undefined)$/i.test(v.trim())
    )
  );
}

function limpiarTexto(v) {
  return String(v ?? '')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
}

function tieneSolicitudEstructurada(v) {
  const tiene = (...keys) =>
    keys.some(key => presente(v[key]));

  return (
    tiene(
      'servicio',
      'service',
      'servicio_confirmado',
      'servicio_canonico'
    ) &&
    tiene(
      'sucursal_solicitada',
      'sucursal',
      'sucursal_id',
      'branch'
    ) &&
    tiene('fecha', 'date', 'fecha ', 'fecha   ') &&
    tiene('numero_personas', 'personas', 'people') &&
    tiene('modo_busqueda', 'search_mode')
  );
}

// Compatibilidad limitada con solicitudes explícitas.
// No inventa datos ausentes.
function solicitudTexto(raw) {
  const t = raw
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

  const out = {};

  function unico(key, values) {
    const valores = [...new Set(values)];

    if (valores.length > 1) {
      erroresTransporte.push('Texto ambiguo: ' + key);
    } else if (valores.length === 1) {
      out[key] = valores[0];
    }
  }

  unico(
    'fecha',
    [...t.matchAll(/\b\d{4}-\d{2}-\d{2}\b/g)]
      .map(m => m[0])
  );

  unico(
    'numero_personas',
    [...t.matchAll(/\b(\d+)\s+personas?\b/g)]
      .map(m => Number(m[1]))
  );

  const branches = {
    '24077': '24077',
    '24079': '24079',
    '24080': '24080',
    '24082': '24082',
    '24221': '24221',
    'del valle': '24077',
    valle: '24077',
    polanco: '24079',
    juarez: '24080',
    lomas: '24082',
    roma: '24221',
  };

  unico(
    'sucursal',
    [
      ...t.matchAll(
        /\bsucursal\s+(del valle|valle|polanco|juarez|lomas|roma|24077|24079|24080|24082|24221)(?:\s*\((\d+)\))?/g
      ),
    ].flatMap(m =>
      m[2]
        ? [branches[m[1]], branches[m[2]] || 'ID_NO_VALIDO']
        : [branches[m[1]]]
    )
  );

  unico(
    'servicio',
    [
      ...t.matchAll(
        /\b(full day spa|premium day spa(?: facial)?|budha 70|buddha 70|temazcal bliss|elephant glow)(?:\s+(individual|pareja|tribu))?\b/g
      ),
    ].map(m =>
      (
        m[1].replace('buddha', 'budha') +
        (m[2] ? ' ' + m[2] : '')
      ).replace(/ /g, '_')
    )
  );

  unico(
    'solicitud_id',
    [...raw.matchAll(/\bsol_[A-Za-z0-9_]+\b/g)]
      .map(m => m[0])
  );

  unico(
    'subscriber_id',
    [...t.matchAll(/\bsubscriber_id\s*[:=]\s*(\d+)\b/g)]
      .map(m => m[1])
  );

  const horas = [
    ...t.matchAll(
      /\b(?:horario|hora preferida|a las)\s*[:=]?\s*(\d{1,2}(?::\d{2})?)(?:\s*(am|pm))?\b/g
    ),
  ].map(m => m[1] + (m[2] ? ' ' + m[2] : ''));

  unico('horario', horas);

  const dia =
    /\bdia completo\b|\bsin hora preferida\b/.test(t);

  const tarde = /\bpor la tarde\b/.test(t);

  if (
    (dia && horas.length) ||
    (tarde && (dia || horas.length))
  ) {
    erroresTransporte.push(
      'Texto ambiguo: modo de búsqueda y horario'
    );
  }

  out.modo_busqueda = tarde
    ? 'tarde'
    : dia
      ? 'dia_completo'
      : horas.length
        ? 'hora_preferida'
        : null;

  if (
    out.servicio &&
    out.sucursal &&
    out.fecha &&
    out.numero_personas &&
    out.modo_busqueda
  ) {
    capas.push(out);
    return;
  }

  erroresTransporte.push(
    'INPUT_TEXTO_NO_ESTRUCTURADO: enviar servicio, sucursal, ' +
    'fecha, numero_personas y modo_busqueda como campos o JSON'
  );
}

function objeto(v, nivel = 0) {
  if (nivel > 8 || v == null) return;

  if (typeof v === 'string') {
    const texto = limpiarTexto(v);
    if (!texto) return;

    let parsed;

    try {
      parsed = JSON.parse(texto);
    } catch {
      if (/^[{\[]/.test(texto)) {
        erroresTransporte.push(
          'El input no contiene JSON válido'
        );
      } else {
        solicitudTexto(texto);
      }

      return;
    }

    objeto(parsed, nivel + 1);
    return;
  }

  if (Array.isArray(v)) {
    if (v.length === 1) {
      objeto(v[0], nivel + 1);
    } else {
      erroresTransporte.push(
        'Se recibió más de una solicitud en el mismo input'
      );
    }

    return;
  }

  if (typeof v !== 'object') return;

  capas.push(v);

  const estructurada = tieneSolicitudEstructurada(v);

  for (const key of [
    'input',
    'query',
    'solicitud',
    'workflowInputs',
    'body',
    'data',
    'json',
    'booking_state',
  ]) {
    if (v[key] == null) continue;

    // Si los campos necesarios ya están presentes, el texto
    // narrativo de input no debe provocar otro error de extracción.
    // Un input con apariencia de JSON sí continúa validándose.
    if (
      key === 'input' &&
      estructurada &&
      typeof v[key] === 'string'
    ) {
      const texto = limpiarTexto(v[key]);

      if (!/^[{\[]/.test(texto)) {
        continue;
      }
    }

    objeto(v[key], nivel + 1);
  }
}

objeto(raiz);

function obtener(...nombres) {
  // Los campos planos explícitos tienen prioridad
  // sobre los valores de los envoltorios.
  for (const capa of capas) {
    for (const nombre of nombres) {
      if (presente(capa[nombre])) {
        return capa[nombre];
      }
    }
  }

  return null;
}

const normalizada = {
  subscriber_id: obtener(
    'subscriber_id',
    'subscriberId',
    'session_id',
    'sessionId'
  ),

  solicitud_id: obtener('solicitud_id'),

  servicio: obtener(
    'servicio',
    'service',
    'servicio_confirmado',
    'servicio_canonico'
  ),

  servicio_confirmado: obtener(
    'servicio_confirmado',
    'servicio_canonico',
    'servicio',
    'service'
  ),

  sucursal: obtener(
    'sucursal_solicitada',
    'sucursal',
    'sucursal_id',
    'branch'
  ),

  fecha: obtener('fecha', 'date', 'fecha ', 'fecha   '),

  numero_personas: obtener(
    'numero_personas',
    'personas',
    'people'
  ),

  horario: obtener(
    'horario',
    'hora',
    'time',
    'horario_normalizado',
    'horario '
  ),

  modo_busqueda: obtener('modo_busqueda', 'search_mode'),

  hora_minima: obtener('hora_minima'),
  es_feriado: obtener('es_feriado'),
  live_chat_url: obtener('live_chat_url'),
  canal_origen: obtener('canal_origen'),

  errores_transporte: [...new Set(erroresTransporte)],
  entrada_desenvuelta: capas.length > 1,
};

normalizada.servicio_confirmado =
  normalizada.servicio_confirmado || normalizada.servicio;

normalizada.sucursal_solicitada = normalizada.sucursal;

// El ID de llamada call_... nunca se usa como ID del contacto.
// La validación posterior sigue revisando los valores recibidos.
return [{ json: normalizada }];

const d = $input.first().json ?? {};

const candidatos = [
  d.subscriber_id,
  d.subscriberId,
  d.suscriber_id,
  d.body?.subscriber_id,
  d.body?.subscriberId,
  d.body?.id,
  d.contact?.subscriber_id,
  d.session_id,
  d.sessionId,
];

const encontrado = candidatos.find(
  (value) => value !== null && value !== undefined && String(value).trim() !== ''
);
const subscriberId = String(encontrado ?? '').trim();
if (!subscriberId) throw new Error('No se pudo identificar subscriber_id al inicio de la ejecución');

const executionId = String($execution?.id ?? '').trim();
const workflowId = String($workflow?.id ?? '').trim();
const workflowName = String($workflow?.name ?? '').trim();
if (!executionId || executionId === 'undefined' || executionId === 'null') {
  throw new Error('n8n no proporcionó un execution_id válido');
}
if (!workflowId || workflowId === 'undefined' || workflowId === 'null') {
  throw new Error('n8n no proporcionó un workflow_id válido');
}

const urlN8n =
  'https://n8n.insidespa.com.mx/workflow/' + encodeURIComponent(workflowId) +
  '/execution/' + encodeURIComponent(executionId);
const liveChatRecibido = String(d.live_chat_url ?? d.body?.live_chat_url ?? '').trim();
const liveChatUrl = /^https:\/\/app\.manychat\.com\//i.test(liveChatRecibido)
  ? liveChatRecibido
  : 'https://app.manychat.com/fb1346079/chat/' + encodeURIComponent(subscriberId);

return [{
  json: {
    ...d,
    subscriber_id: subscriberId,
    n8n_execution_id: executionId,
    n8n_workflow_id: workflowId,
    n8n_workflow_name: workflowName,
    url_n8n: urlN8n,
    live_chat_url: liveChatUrl,
  },
}];

const d = $input.first().json;
return [{ json: {
  ok: false,
  estado: 'DATOS_INVALIDOS',
  disponible: false,
  errores: d.errores_entrada || ['Datos incompletos'],
  errores_entrada: d.errores_entrada || [],
  mensaje: '📝 Antes de buscar disponibilidad necesitamos corregir: ' + (d.errores_entrada || []).join(', '),
  solo_consulta: true,
  guardar_borrador: false,
  crear_cita_pabau: false
} }];

// Selección de presentación: recibe únicamente opciones ya verificadas.
// No crea horas, no cambia recursos y no añade límites de disponibilidad.
function seleccionarHorariosVariados(opciones) {
  const porHora = new Map();
  for (const opcion of opciones || []) {
    if (!opcion || opcion.disponible === false) continue;
    const m = String(opcion.hora_inicio || '').trim().match(/^(\d{1,2}):(\d{2})$/);
    if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) continue;
    const minuto = Number(m[1]) * 60 + Number(m[2]);
    // En otra sucursal, conservar el orden previo para desempatar la misma hora.
    if (!porHora.has(minuto)) porHora.set(minuto, { minuto, opcion });
  }
  const candidatas = [...porHora.values()].sort((a,b) => a.minuto-b.minuto);
  if (candidatas.length <= 3) return candidatas.map(x => x.opcion);
  // Son referencias flexibles; todos los candidatos conservan elegibilidad.
  const referencias = [11*60, 14*60+20, 17*60];
  let mejor = null;
  for (let i=0; i<candidatas.length-2; i++) {
    for (let j=i+1; j<candidatas.length-1; j++) {
      for (let k=j+1; k<candidatas.length; k++) {
        const trio = [candidatas[i],candidatas[j],candidatas[k]];
        const distancia = trio.reduce((total,x,n) => total+Math.abs(x.minuto-referencias[n]),0);
        const separacion = Math.min(trio[1].minuto-trio[0].minuto,trio[2].minuto-trio[1].minuto);
        const amplitud = trio[2].minuto-trio[0].minuto;
        if (!mejor || distancia<mejor.distancia ||
          (distancia===mejor.distancia && (separacion>mejor.separacion ||
          (separacion===mejor.separacion && amplitud>mejor.amplitud)))) {
          mejor = { trio, distancia, separacion, amplitud };
        }
      }
    }
  }
  return mejor.trio.map(x => x.opcion);
}

const nombres = {
  '24077': 'Valle',
  '24079': 'Polanco',
  '24080': 'Juárez',
  '24082': 'Lomas',
  '24221': 'Roma'
};
const ordenSucursales = ['24077', '24079', '24080', '24082', '24221'];

function limpiar(valor) {
  return String(valor ?? '').trim();
}

function normalizarTexto(valor) {
  return limpiar(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function sucursalId(valor) {
  const mapa = {
    '24077': '24077', valle: '24077', 'del valle': '24077',
    '24079': '24079', polanco: '24079', polanquito: '24079',
    '24080': '24080', juarez: '24080', 'centro juarez': '24080',
    '24082': '24082', lomas: '24082', 'lomas de chapultepec': '24082',
    '24221': '24221', roma: '24221', 'roma norte': '24221', 'colonia roma': '24221'
  };
  return mapa[normalizarTexto(valor)] || limpiar(valor);
}

function aBooleano(valor) {
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sí', 'yes'].includes(normalizarTexto(valor));
}

function tieneFormaResultado(valor) {
  return valor && typeof valor === 'object' && !Array.isArray(valor) && (
    valor.sucursal !== undefined ||
    valor.sucursal_solicitada !== undefined ||
    valor.opcion_exacta !== undefined ||
    valor.resultado_principal !== undefined ||
    valor.alternativas !== undefined ||
    valor.alternativas_cercanas !== undefined ||
    valor.estado !== undefined
  );
}

function desenvolver(valor, profundidad = 0) {
  if (profundidad > 5 || valor === undefined || valor === null) return [];
  if (Array.isArray(valor)) {
    return valor.flatMap((item) => desenvolver(item, profundidad + 1));
  }
  if (typeof valor !== 'object') return [];
  if (tieneFormaResultado(valor)) return [valor];

  for (const clave of ['json', 'output', 'data', 'result']) {
    if (valor[clave] && typeof valor[clave] === 'object') {
      const encontrados = desenvolver(valor[clave], profundidad + 1);
      if (encontrados.length) return encontrados;
    }
  }
  return [];
}

let solicitud = {};
try {
  solicitud = $('Normalizar solicitud global').first().json || {};
} catch {}

const resultados = $input.all()
  .flatMap((item) => desenvolver(item?.json ?? item))
  .map((resultado) => ({
    ...resultado,
    sucursal: sucursalId(resultado.sucursal || resultado.nombre_sucursal)
  }))
  .filter((resultado) => ordenSucursales.includes(String(resultado.sucursal)))
  .sort((a, b) => ordenSucursales.indexOf(String(a.sucursal)) - ordenSucursales.indexOf(String(b.sucursal)));

const primera = resultados[0] || {};
const sucursalSolicitada = sucursalId(
  solicitud.sucursal_solicitada ||
  solicitud.sucursal ||
  primera.sucursal_solicitada ||
  primera.sucursal
);
const horarioSolicitado = limpiar(
  solicitud.horario_normalizado ||
  solicitud.horario ||
  primera.horario_solicitado ||
  primera.horario
) || null;
const fecha = limpiar(solicitud.fecha || primera.fecha) || null;
const servicio = limpiar(solicitud.servicio_confirmado || solicitud.servicio || primera.servicio_confirmado || primera.servicio) || null;

const conflictos=resultados.filter(r=>r.ok===true && String(r.servicio_confirmado||r.servicio||'')!==servicio);
if(conflictos.length)return [{json:{ok:false,estado:'SERVICIO_NO_COINCIDE',servicio,solicitud_id:solicitud.solicitud_id||'',disponible:false,hay_disponibilidad:false,opciones_para_cliente:[],mensaje:'La consulta recibió resultados de otra experiencia. Requiere revisión antes de ofrecer horarios.',solo_consulta:true,guardar_borrador:false,crear_cita_pabau:false}}];

const modoBusqueda = solicitud.modo_busqueda || (horarioSolicitado ? 'hora_preferida' : 'dia_completo');
const horaMinima = modoBusqueda === 'tarde' ? (limpiar(solicitud.hora_minima) || '15:20') : null;

function normalizarOpcion(opcion, resultado) {
  if (!opcion || typeof opcion !== 'object') return null;
  const sucursal = sucursalId(opcion.sucursal || resultado?.sucursal);
  const hora = limpiar(opcion.hora_inicio || opcion.horario || opcion.hora_jacuzzi || opcion.hora_masaje || opcion.hora);
  const horaJacuzzi = limpiar(opcion.hora_jacuzzi) || null;
  const horaMasaje = limpiar(opcion.hora_masaje) || null;
  if (!ordenSucursales.includes(sucursal) || !/^([01]?\d|2[0-3]):[0-5]\d$/.test(hora)) return null;
  if (opcion.disponible===false || String(opcion.fecha || resultado?.fecha || fecha)!==String(fecha)) return null;
  if (String(opcion.servicio || resultado?.servicio_confirmado || resultado?.servicio || servicio)!==String(servicio)) return null;
  if (sucursal!==String(resultado?.sucursal)) return null;
  return {
    ...opcion,
    sucursal,
    nombre_sucursal: nombres[sucursal] || opcion.nombre_sucursal || sucursal,
    misma_sucursal: sucursal===sucursalSolicitada,
    fecha: limpiar(opcion.fecha || resultado?.fecha || fecha) || null,
    hora_inicio: hora,
    horario: hora,
    hora_jacuzzi: horaJacuzzi,
    hora_masaje: horaMasaje
  };
}

function opcionExacta(resultado) {
  if (!resultado || resultado.ok!==true || resultado.error) return null;
  const opcion = resultado.opcion_exacta || resultado.resultado_principal;
  const marcadaDisponible =
    aBooleano(resultado.disponible) ||
    ['DISPONIBLE_EXACTO', 'DISPONIBLE_SUCURSAL_SOLICITADA'].includes(String(resultado.estado || ''));
  return marcadaDisponible ? normalizarOpcion(opcion, resultado) : null;
}

function alternativasDe(resultado) {
  if (!resultado || resultado.ok!==true || resultado.error) return [];
  const lista = Array.isArray(resultado.alternativas)
    ? resultado.alternativas
    : (Array.isArray(resultado.alternativas_disponibles)
      ? resultado.alternativas_disponibles
      : (Array.isArray(resultado.alternativas_cercanas)
        ? resultado.alternativas_cercanas
        : []));
  return lista.map((opcion) => normalizarOpcion(opcion, resultado)).filter(Boolean).filter(cumpleHoraMinima);
}

function sinDuplicados(opciones) {
  const vistas = new Set();
  return opciones.filter((opcion) => {
    const clave = [opcion.sucursal, opcion.fecha, opcion.hora_inicio].join('|');
    if (vistas.has(clave)) return false;
    vistas.add(clave);
    return true;
  });
}

const solicitado = resultados.find((resultado) => String(resultado.sucursal) === sucursalSolicitada);
const exactaSolicitada = modoBusqueda === 'tarde' ? null : opcionExacta(solicitado);

const exactasOtras = resultados
  .filter(() => modoBusqueda !== 'tarde')
  .filter((resultado) => String(resultado.sucursal) !== sucursalSolicitada)
  .map((resultado) => opcionExacta(resultado))
  .filter(Boolean)
  .map((opcion) => ({
    ...opcion,
    tipo_opcion: 'MISMA_HORA_OTRA_SUCURSAL'
  }));

const alternativasSolicitada = alternativasDe(solicitado).map((opcion) => ({
  ...opcion,
  tipo_opcion: 'HORARIO_DISPONIBLE_MISMA_SUCURSAL'
}));

const alternativasOtras = resultados
  .filter((resultado) => String(resultado.sucursal) !== sucursalSolicitada)
  .flatMap((resultado) => alternativasDe(resultado).map((opcion) => ({
    ...opcion,
    tipo_opcion: 'HORARIO_DISPONIBLE_OTRA_SUCURSAL'
  })));

function minutosHora(valor) {
  const match = limpiar(valor).match(/^(\d{1,2}):(\d{2})$/);
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
}

function cumpleHoraMinima(opcion) {
  if (modoBusqueda !== 'tarde') return true;
  const minuto = minutosHora(opcion?.hora_inicio);
  const minimo = minutosHora(horaMinima || '15:20');
  return minuto !== null && minimo !== null && minuto >= minimo;
}

function ordenarPorCercania(opciones, minutoReferencia) {
  const lista = [...opciones];
  lista.sort((a, b) => {
    const minutoA = minutosHora(a.hora_inicio);
    const minutoB = minutosHora(b.hora_inicio);

    if (minutoReferencia !== null) {
      const distanciaA = minutoA === null
        ? Number.MAX_SAFE_INTEGER
        : Math.abs(minutoA - minutoReferencia);
      const distanciaB = minutoB === null
        ? Number.MAX_SAFE_INTEGER
        : Math.abs(minutoB - minutoReferencia);
      if (distanciaA !== distanciaB) return distanciaA - distanciaB;

      // En un empate se prefiere el horario posterior al solicitado.
      const futuroA = minutoA !== null && minutoA >= minutoReferencia ? 0 : 1;
      const futuroB = minutoB !== null && minutoB >= minutoReferencia ? 0 : 1;
      if (futuroA !== futuroB) return futuroA - futuroB;
    }

    const ordenA = ordenSucursales.indexOf(String(a.sucursal));
    const ordenB = ordenSucursales.indexOf(String(b.sucursal));
    if (ordenA !== ordenB) return ordenA - ordenB;
    return (minutoA ?? Number.MAX_SAFE_INTEGER) - (minutoB ?? Number.MAX_SAFE_INTEGER);
  });
  return lista;
}

const minutoSolicitado = modoBusqueda === 'tarde'
  ? minutosHora(horaMinima || '15:20')
  : minutosHora(horarioSolicitado);
const alternativasMismaSucursal = modoBusqueda === 'dia_completo' && !horarioSolicitado
  ? seleccionarHorariosVariados(ordenarPorCercania(sinDuplicados(alternativasSolicitada), null))
  : ordenarPorCercania(sinDuplicados(alternativasSolicitada), minutoSolicitado).slice(0, 3);
const alternativasOtrasSucursales = modoBusqueda === 'dia_completo' && !horarioSolicitado
  ? seleccionarHorariosVariados(ordenarPorCercania(sinDuplicados(alternativasOtras), null))
  : ordenarPorCercania(sinDuplicados(alternativasOtras), minutoSolicitado).slice(0, 3);
const exactasOtrasOrdenadas = sinDuplicados(exactasOtras)
  .sort((a, b) =>
