// Identidad exacta del servicio. Las filas vigentes se leen de Google Sheets.
function spaNorm(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/buddha|budhas|budas|buda\b/g, 'budha')
    .replace(/fulldayspa/g, 'full day spa').replace(/3\s*p(?:x|ax)\b/g, 'tribu')
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function spaFamily(v, n) {
  let t = spaNorm(v).replace(/^(masaje|jacuzzi) /, '');
  t = t.replace(/^sauna elephant glow/, 'elephant glow').replace(/^premium budha/, 'budha');
  const m = t.match(/^(premium(?: day(?: spa)?)?(?: facial)?|full(?: day(?: spa)?)?|budha(?: 70)?|temazcal bliss|elephant glow)(?: (individual|pareja|tribu))?$/);
  if (!m) return null;
  const root = m[1].startsWith('premium') ? (m[1].includes('facial') ? 'premium_day_spa_facial' : 'premium_day_spa')
    : m[1].startsWith('full') ? 'full_day_spa' : m[1].startsWith('budha') ? 'budha_70' : m[1].replace(/ /g, '_');
  const mod = m[2] || (n === 1 ? 'individual' : n === 2 ? 'pareja' : n >= 3 ? 'tribu' : '');
  return {root, mod, canonical: root + (mod ? '_' + mod : '')};
}
function spaCanonical(v, n) {
  const f = spaFamily(v, n);
  return f ? f.canonical : spaNorm(v).replace(/ /g, '_') || null;
}
const d = $('Desenvolver parámetros de disponibilidad').first().json || {};

function limpiar(v) { return String(v ?? '').trim(); }
function texto(v) {
  return limpiar(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').toLowerCase();
}
function slug(v) { return texto(v).replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, '_').replace(/^_+|_+$/g, ''); }
function sucursal(v) {
  const t = texto(v).replace(/^inside\s+spa\s+/, '').replace(/^sucursal\s+/, '');
  const mapa = {
    '24077':'24077', valle:'24077', 'del valle':'24077',
    '24079':'24079', polanco:'24079', polanquito:'24079',
    '24080':'24080', juarez:'24080', 'centro juarez':'24080',
    '24082':'24082', lomas:'24082', 'lomas de chapultepec':'24082',
    '24221':'24221', roma:'24221', 'roma norte':'24221', 'colonia roma':'24221'
  };
  return mapa[t] || limpiar(v);
}
function hora(v) {
  let h = limpiar(v).toLowerCase();
  if (!h) return null;
  const ampm = h.match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/);
  if (ampm) {
    let hh = Number(ampm[1]); const mm = Number(ampm[2] || 0);
    if (hh < 1 || hh > 12 || mm > 59) return null;
    if (ampm[3] === 'pm' && hh !== 12) hh += 12;
    if (ampm[3] === 'am' && hh === 12) hh = 0;
    return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
  }
  if (/^\d{1,2}$/.test(h)) h += ':00';
  const m = h.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) return null;
  return String(Number(m[1])).padStart(2, '0') + ':' + m[2];
}
function canonico(v,personas) { return spaCanonical(v,personas); }

const personas = Number(d.numero_personas ?? d.personas ?? 0);
const recibido = limpiar(d.servicio_confirmado ?? d.servicio_canonico ?? d.servicio);
const servicio = canonico(recibido, personas);
const sucursalSolicitada = sucursal(d.sucursal_solicitada ?? d.sucursal);
const fecha = limpiar(d.fecha ?? d['fecha   '] ?? d['fecha ']);
const modoRecibido = texto(d.modo_busqueda);
const esTarde = ['tarde', 'vespertino', 'vespertina'].includes(modoRecibido);
const horario = esTarde ? null : hora(d.horario ?? d['horario '] ?? d.hora ?? d.horario_normalizado);
const minimoRecibido = hora(d.hora_minima) || '15:20';
const horaMinima = esTarde ? (minimoRecibido < '15:20' ? '15:20' : minimoRecibido) : null;
const modo = esTarde ? 'tarde' : (horario ? 'hora_preferida' : 'dia_completo');
const errores = [...(Array.isArray(d.errores_transporte) ? d.errores_transporte : [])];
const hOriginal=limpiar(d.horario??d.hora??'');
if(hOriginal&&!esTarde&&!horario)errores.push('Horario inválido');
if(d.servicio && d.servicio_confirmado && spaCanonical(d.servicio,personas)!==spaCanonical(d.servicio_confirmado,personas))errores.push('SERVICIO_NO_COINCIDE');
if (!String(d.subscriber_id??'').trim()) errores.push('Falta subscriber_id: revisar mapeo del bot');
