if (!['24077','24079','24080','24082','24221'].includes(sucursalSolicitada)) errores.push('Sucursal no válida');
const fechaObjeto = /^\d{4}-\d{2}-\d{2}$/.test(fecha) ? new Date(fecha + 'T12:00:00Z') : null;
if (!fechaObjeto || !Number.isFinite(fechaObjeto.getTime()) || fechaObjeto.toISOString().slice(0,10) !== fecha) errores.push('Fecha inválida');
if (!Number.isInteger(personas) || personas < 1) errores.push('Número de personas inválido');

return [{json:{
  canal_origen: limpiar(d.canal_origen), solicitud_id: limpiar(d.solicitud_id), servicio_busqueda: recibido, subscriber_id: limpiar(d.subscriber_id), live_chat_url: limpiar(d.live_chat_url), servicio, servicio_confirmado: servicio,
  sucursal_solicitada: sucursalSolicitada, fecha, horario, horario_normalizado: horario,
